"""Contract tests for SQL role levels in economic charges (no real SQL calls)."""
import ast
import asyncio
from pathlib import Path
from types import SimpleNamespace
import pytest

SOURCE = Path(__file__).resolve().parents[1] / "modules/fase2_operativo/services/cargos_service.py"
LEVELS = {"SUPERVISOR": 50, "GERENTE_OPS": 60, "DIRECCION": 80, "ADMIN": 90, "SUPERADMIN": 100}

class PermisoInsuficienteError(Exception):
    pass

def load_check(levels=None):
    tree = ast.parse(SOURCE.read_text(encoding="utf-8"))
    cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == "CargosService")
    fn = next(n for n in cls.body if isinstance(n, ast.AsyncFunctionDef) and n.name == "_validar_permiso_por_monto")
    namespace = {
        "get_role_level": lambda user: (LEVELS if levels is None else levels).get(user.get("role"), 0),
        "PermisoInsuficienteError": PermisoInsuficienteError,
    }
    exec(compile(ast.fix_missing_locations(ast.Module(body=[fn], type_ignores=[])), str(SOURCE), "exec"), namespace)
    return namespace["_validar_permiso_por_monto"]

@pytest.mark.parametrize("role,amount,allowed", [
    ("SUPERVISOR", 500, True), ("SUPERVISOR", 501, False),
    ("GERENTE_OPS", 2000, True), ("GERENTE_OPS", 2001, False),
    ("DIRECCION", 2001, True), ("ADMIN", 2001, True),
    ("SUPERADMIN", 50000, True), ("DESCONOCIDO", 100, False),
])
def test_montos(role, amount, allowed):
    fn = load_check()
    host = SimpleNamespace(UMBRAL_SUPERVISOR=500, UMBRAL_GERENTE=2000)
    if allowed:
        asyncio.run(fn(host, amount, role, "AUTORIZAR"))
    else:
        with pytest.raises(PermisoInsuficienteError):
            asyncio.run(fn(host, amount, role, "AUTORIZAR"))

def test_sql_sin_niveles_deniega():
    fn = load_check(levels={})
    host = SimpleNamespace(UMBRAL_SUPERVISOR=500, UMBRAL_GERENTE=2000)
    with pytest.raises(PermisoInsuficienteError):
        asyncio.run(fn(host, 100, "SUPERADMIN", "AUTORIZAR"))

def test_reversa_no_usa_jerarquia_local():
    source = SOURCE.read_text(encoding="utf-8")
    tree = ast.parse(source)
    cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == "CargosService")
    fn = next(n for n in cls.body if isinstance(n, ast.AsyncFunctionDef) and n.name == "revertir_cargo")
    body = ast.get_source_segment(source, fn)
    assert "get_role_level" in body
    assert "JERARQUIA_ROLES" not in body
